package main

import (
	"bytes"
	"go/format"
	"os"
)

const source = `// Code generated by example upstream; DO NOT EDIT.
package main

type Model struct {
 Name string
 _id string
 Values [2]int
 Labels map[string]string
}
`

func main() {
	data, err := format.Source([]byte(source))
	if err != nil {
		panic(err)
	}
	if previous, err := os.ReadFile("models.go"); err == nil && bytes.Equal(previous, data) {
		return
	}
	if err := os.WriteFile("models.go", data, 0644); err != nil {
		panic(err)
	}
}
